import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {mkdtemp,readFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {createHash} from 'node:crypto';
import {insightScenario} from '../../server/test/insight-helpers.js';
async function cliContext(scenario,fn){
  const created=(await scenario.api('POST','/tokens',{name:'Insight CLI',scopes:['*']})).data;
  const cli=args=>new Promise((resolve,reject)=>{
    const child=spawn(process.execPath,[fileURLToPath(new URL('../bin/crew.js',import.meta.url)),...args,'--url',scenario.server.url,'--token',created.token,'--json']);
    let stdout='',stderr='';const timer=setTimeout(()=>{child.kill('SIGKILL');reject(new Error('CLI test deadline'));},10000);
    child.stdout.on('data',chunk=>stdout+=chunk);child.stderr.on('data',chunk=>stderr+=chunk);
    child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);try{resolve({code,data:stdout&&!args.includes('--help')?JSON.parse(stdout):null,stdout,stderr});}catch(error){reject(error);}});
  });
  return fn(cli);
}
test('actual streamed export refuses overwrite and reports exact file bytes and hash',()=>insightScenario(s=>cliContext(s,async cli=>{
  const directory=await mkdtemp(tmpdir()+'/crew-transfer-cli-');
  try{
    const output=directory+'/project.json',result=await cli(['export',s.project.id,'--output',output]);assert.equal(result.code,0,result.stderr);
    const bytes=await readFile(output);assert.equal(result.data.bytes,bytes.length);assert.equal(result.data.sha256,createHash('sha256').update(bytes).digest('hex'));assert.equal(JSON.parse(bytes).issues[0].id,s.issue.id);
    assert.equal((await cli(['export',s.project.id,'--output',output])).code,1);assert.deepEqual(await readFile(output),bytes);
    const csv=await cli(['export',s.project.id,'--format','csv','--output',directory+'/project.csv']);assert.equal(csv.code,0,csv.stderr);assert.match(await readFile(directory+'/project.csv','utf8'),/"number","title"/);
  }finally{await rm(directory,{recursive:true,force:true});}
})));
test('actual streamed import preview writes nothing and confirmed import remaps a real project',()=>insightScenario(s=>cliContext(s,async cli=>{
  const directory=await mkdtemp(tmpdir()+'/crew-import-cli-');
  try{
    const output=directory+'/project.json';await cli(['export',s.project.id,'--output',output]);
    assert.equal((await cli(['import','--org',s.org.id,'--file',output,'--key','COPY'])).code,1);
    const preview=await cli(['import','--org',s.org.id,'--file',output,'--key','COPY','--preview']);assert.equal(preview.code,0,preview.stderr);assert.equal(preview.data.preview.counts.issues,1);
    assert.equal(s.server.ctx.db.prepare("SELECT count(*) n FROM projects WHERE key='COPY'").get().n,0);
    const imported=await cli(['import','--org',s.org.id,'--file',output,'--key','COPY','--yes']);assert.equal(imported.code,0,imported.stderr);assert.equal(imported.data.counts.issues,1);assert.notEqual(imported.data.mappings.issues[s.issue.id],s.issue.id);
  }finally{await rm(directory,{recursive:true,force:true});}
})));
test('actual dashboard CLI returns scoped real counts and all transfer families expose help',()=>insightScenario(s=>cliContext(s,async cli=>{
  const report=await cli(['dashboard','--org',s.org.id,'--project',s.project.id]);assert.equal(report.code,0,report.stderr);assert.equal(report.data.totals.issues,1);
  for(const group of ['dashboard','export','import'])assert.match((await cli([group,'--help'])).stdout,new RegExp('crew '+group));
})));

import test from 'node:test';
import assert from 'node:assert/strict';
import {insightScenario} from './insight-helpers.js';
function seedChoices(s,count=205) {
  const {db}=s.server.ctx,time=s.server.ctx.now();
  s.server.ctx.transaction(()=>{
    for(let index=0;index<count;index++) {
      const suffix=String(index).padStart(3,'0');
      db.prepare('INSERT INTO organizations VALUES (?,?,?,?)').run('options-org-'+suffix,'Later organization '+suffix,time,time);
      db.prepare('INSERT INTO memberships VALUES (?,?,?,?,?)').run('options-org-'+suffix,s.user.id,'owner',time,time);
      db.prepare('INSERT INTO projects(id,org_id,key,name,description,created_at,updated_at) VALUES (?,?,?,?,?,?,?)').run('options-project-'+suffix,s.org.id,'Z'+suffix,'Later project '+suffix,'Searchable detail '+suffix,time,time);
      db.prepare('INSERT INTO issues(id,project_id,number,title,description,status_id,priority,created_by,rank,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').run('options-issue-'+suffix,s.project.id,1000+index,'Later issue '+suffix,'',s.project.statuses[0].id,0,s.user.id,index,time,time);
    }
  });
}
test('authorized organization project and issue selectors reach records beyond first200',()=>insightScenario(async s=>{
  seedChoices(s);
  for(const [type,q,id] of [['organizations','Later organization 204','options-org-204'],['projects','Later project 204','options-project-204'],['issues','Later issue 204','options-issue-204']]){
    const result=await s.api('GET','/insight/options?'+new URLSearchParams({type,orgId:s.org.id,q,limit:20}));assert.equal(result.status,200);assert.equal(result.data.total,1);assert.equal(result.data.items[0].id,id);
  }
}));
test('selector cursors traverse every authorized item and selected ID resolves outside current page',()=>insightScenario(async s=>{
  seedChoices(s);
  const first=(await s.api('GET','/insight/options?type=projects&orgId='+s.org.id+'&limit=20')).data;assert.equal(first.items.length,20);assert(first.nextCursor);
  assert(!first.items.some(item=>item.id==='options-project-204'));
  const selected=(await s.api('GET','/insight/options?type=projects&orgId='+s.org.id+'&id=options-project-204&limit=1')).data;assert.equal(selected.items[0].label,'Z204 · Later project 204');
  const second=(await s.api('GET','/insight/options?type=projects&orgId='+s.org.id+'&limit=20&cursor='+encodeURIComponent(first.nextCursor))).data;assert.equal(second.items.length,20);assert(!second.items.some(item=>first.items.some(old=>old.id===item.id)));
}));
test('lookup matching totals and selected identity never disclose revoked or hidden projects',()=>insightScenario(async s=>{
  seedChoices(s,2);
  await s.api('PATCH','/orgs/'+s.org.id+'/members/'+s.memberUser.id,{role:'guest'});
  await s.api('POST','/projects/'+s.project.id+'/guests',{userId:s.memberUser.id});
  const visible=(await s.member('GET','/insight/options?type=projects&orgId='+s.org.id)).data;assert.equal(visible.total,1);assert.equal(visible.items[0].id,s.project.id);
  assert.equal((await s.member('GET','/insight/options?type=projects&orgId='+s.org.id+'&q=Later')).data.total,0);
  assert.deepEqual((await s.member('GET','/insight/options?type=projects&orgId='+s.org.id+'&id=options-project-000')).data.items,[]);
  await s.api('DELETE','/projects/'+s.project.id+'/guests/'+s.memberUser.id);
  assert.deepEqual((await s.member('GET','/insight/options?type=issues&orgId='+s.org.id+'&id='+s.issue.id)).data.items,[]);
}));
test('selector permission context cannot weaken fixed insight and organization scopes',()=>insightScenario(async s=>{
  const token=(await s.api('POST','/tokens',{name:'Insufficient selector scope',scopes:['project:read','org:read']})).data.token;
  assert.equal((await s.api('GET','/insight/options?type=users&permission=project:read&orgId='+s.org.id,undefined,{Authorization:'Bearer '+token})).status,403);
  assert.equal((await s.api('GET','/insight/options?type=users&orgId=foreign')).status,403);
  assert.equal((await s.api('GET','/insight/options?type=issues&orgId='+s.org.id+'&permission=org:manage')).status,422);
}));
test('watch lookup exposes current target summaries and exact target state',()=>insightScenario(async s=>{
  const result=(await s.api('GET','/subscriptions?orgId='+s.org.id+'&targetType=issue&targetId='+s.issue.id)).data;
  assert.equal(result.items.length,1);assert.equal(result.items[0].target.label,s.issue.key+' · '+s.issue.title);
  await s.api('DELETE','/subscriptions/issue/'+s.issue.id);
  assert.deepEqual((await s.api('GET','/subscriptions?orgId='+s.org.id+'&targetType=issue&targetId='+s.issue.id)).data.items,[]);
}));
test('dashboard current-set drilldown leaves historical project throughput independent',()=>insightScenario(async s=>{
  await s.api('PATCH','/issues/'+s.issue.id,{statusId:s.project.statuses.find(status=>status.category==='done').id});
  const open=(await s.api('POST','/projects/'+s.project.id+'/issues',{title:'Current open',priority:4})).data.issue;
  const report=(await s.api('GET','/dashboard?orgId='+s.org.id+'&projectId='+s.project.id+'&statusId='+open.statusId+'&priority=4&issueLimit=1')).data;
  assert.equal(report.totals.issues,1);assert.equal(report.issuePage.items[0].id,open.id);assert.equal(report.throughput.at(-1).issues,1);assert.equal(report.filters.priority,4);
}));

import test from 'node:test';
import assert from 'node:assert/strict';
import {pickerScope,emptyPicker,scopedPicker,pickerAction,selectedOption} from '../src/pages/insight/selector-state.js';
import {createRequestGuard,guardedResult} from '../src/pages/insight/request-guard.js';
import {recordPage,previewValue,previewCatalog} from '../src/pages/insight/record-browser-state.js';
import {parseProjectFile} from '../src/pages/insight/transfer-state.js';
test('ordinary selector rerenders preserve pagination while organization change resets query cursor and history',()=>{
  const first=pickerScope({type:'projects',orgId:'a'}),other=pickerScope({type:'projects',orgId:'b'});
  let state=emptyPicker(first);state=pickerAction(state,{type:'draft',value:'late'});state=pickerAction(state,{type:'search'});state=pickerAction(state,{type:'next',cursor:'next'});
  assert.equal(scopedPicker(state,first),state);assert.deepEqual(scopedPicker(state,other),emptyPicker(other));
});
test('selected entity labels remain available outside the current search page',()=>{assert.deepEqual(selectedOption([{id:'first'}],'later',{items:[{id:'later',label:'Visible later item'}]}),{id:'later',label:'Visible later item'});assert.equal(selectedOption([],'revoked',{items:[]}),null);});
test('new file or organization invalidates delayed preview without authorizing another draft',async()=>{
  const guard=createRequestGuard(),old=guard.begin(),applied=[];let resolve;
  const delayed=new Promise(done=>resolve=done).then(value=>guardedResult(guard,old,item=>applied.push(item),value));
  guard.invalidate();const current=guard.begin();resolve({project:'old'});assert.equal(await delayed,false);assert.deepEqual(applied,[]);
  assert.equal(guardedResult(guard,current,item=>applied.push(item),{project:'new'}),true);assert.deepEqual(applied,[{project:'new'}]);
});
test('new action and component disposal suppress earlier digest watch and import responses',()=>{
  const guard=createRequestGuard(),old=guard.begin(),latest=guard.begin();assert(old.signal.aborted);assert.equal(guard.current(old),false);assert.equal(guard.current(latest),true);guard.invalidate();assert(latest.signal.aborted);assert.equal(guardedResult(guard,latest,()=>{throw new Error('must not run');},{}),false);
});
test('bounded preview pages search complete catalogs and clamp a stale page after filter changes',()=>{
  const items=Array.from({length:205},(_,id)=>({id,name:'Record '+id}));let result=recordPage(items,{page:10,size:20,columns:[{key:'name'}]});assert.equal(result.items.length,5);assert.equal(result.from,201);
  result=recordPage(items,{query:'Record 204',page:10,size:20,columns:[{key:'name'}]});assert.equal(result.page,0);assert.equal(result.total,1);assert.equal(result.items[0].id,204);
});
test('record previews resolve readable status people parents and labels without dumping opaque graphs',()=>{
  const document={statuses:[{id:'s',name:'Doing'}],users:[{id:'u',name:'Alex',email:'a@example.test'}],labels:[{id:'l',name:'Release'}],issues:[{id:'i',number:2,title:'Child',statusId:'s',assigneeId:'u',parentId:'p',labelIds:['l']},{id:'p',number:1,title:'Parent',labelIds:[]}],comments:[],relations:[]};
  const catalog=previewCatalog(document),issue=document.issues[0],columns=catalog.issues.columns;
  assert.equal(columns.find(column=>column.key==='statusId').value(issue),'Doing');assert.match(columns.find(column=>column.key==='assigneeId').value(issue),/Alex/);assert.equal(columns.find(column=>column.key==='parentId').value(issue),'#1 Parent');assert.equal(previewValue(columns.find(column=>column.key==='labelIds').value(issue)),'Release');
});
test('malformed source records fail file validation before rendering a preview',()=>{
  const document={format:'crew.project',version:1,project:{key:'X',name:'X'},statuses:[],users:[],labels:[],comments:[],relations:[],issues:[null]};assert.throws(()=>parseProjectFile(JSON.stringify(document)),/issues.0/);
  document.issues=[{id:'bad'}];assert.throws(()=>parseProjectFile(JSON.stringify(document)),/labelIds/);
});
